/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'fs'

// Parse a URI reference into its components
function parseURI(uri) {
  const result = {
    scheme: undefined,
    authority: undefined,
    path: '',
    query: undefined,
    fragment: undefined,
  }

  let remaining = uri
  let idx = 0

  // Parse scheme: optional, stops at first : not preceded by /, ?, or #
  const schemeMatch = remaining.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/)
  if (schemeMatch) {
    result.scheme = schemeMatch[1]
    remaining = remaining.slice(schemeMatch[0].length)
  }

  // Parse authority: optional, introduced by // and runs to /, ?, or #
  if (remaining.startsWith('//')) {
    remaining = remaining.slice(2)
    const authorityMatch = remaining.match(/^([^/?#]*)/)
    result.authority = authorityMatch[1]
    remaining = remaining.slice(result.authority.length)
  }

  // Parse query: from ? to #
  const queryMatch = remaining.match(/^([^#]*)(?:#(.*))?$/)
  if (queryMatch) {
    const beforeFragment = queryMatch[1]
    const fragment = queryMatch[2]

    const queryIdx = beforeFragment.indexOf('?')
    if (queryIdx !== -1) {
      result.path = beforeFragment.slice(0, queryIdx)
      result.query = beforeFragment.slice(queryIdx + 1)
    } else {
      result.path = beforeFragment
    }

    if (fragment !== undefined) {
      result.fragment = fragment
    }
  }

  return result
