// Parse authority into userinfo, host, port
function parseAuthority(authority) {
  const result = {
    userinfo: undefined,
    host: '',
    port: undefined,
  }

  if (!authority) return result

  // Split userinfo from host:port
  const lastAtIdx = authority.lastIndexOf('@')
  let hostport = authority
  if (lastAtIdx !== -1) {
    result.userinfo = authority.slice(0, lastAtIdx)
    hostport = authority.slice(lastAtIdx + 1)
  }

  // Parse host and port
  if (hostport.startsWith('[')) {
    // IPv6 address
    const closeBracketIdx = hostport.indexOf(']')
    if (closeBracketIdx !== -1) {
      result.host = hostport.slice(1, closeBracketIdx)
      const afterBracket = hostport.slice(closeBracketIdx + 1)
      if (afterBracket.startsWith(':')) {
        result.port = afterBracket.slice(1)
      }
    }
  } else {
    // IPv4 or domain
    const colonIdx = hostport.indexOf(':')
    if (colonIdx !== -1) {
      result.host = hostport.slice(0, colonIdx)
      result.port = hostport.slice(colonIdx + 1)
    } else {
      result.host = hostport
    }
  }

  return result
}

// Reconstruct authority from parts
function reconstructAuthority(userinfo, host, port) {
  let authority = host
  if (port !== undefined) {
    authority += ':' + port
  }
  if (userinfo !== undefined) {
    authority = userinfo + '@' + authority
  }
  return authority
}

// Reconstruct URI from parts
function reconstructURI(scheme, authority, path, query, fragment) {
  let result = ''
  if (scheme !== undefined) {
    result += scheme + ':'
  }
  if (authority !== undefined) {
    result += '//' + authority
  }
  result += path
  if (query !== undefined) {
    result += '?' + query
  }
  if (fragment !== undefined) {
    result += '#' + fragment
  }
  return result
}

// Check if a character is unreserved
function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

// Check if a character is a hex digit
function isHexDigit(ch) {
  return /^[0-9A-Fa-f]$/.test(ch)
}

// Normalize percent-encodings in a component
function normalizePercentEncodings(component, componentName, lineNum) {
  if (!component) return component

  let result = ''
  let i = 0
  while (i < component.length) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const hex1 = component[i + 1]
      const hex2 = component[i + 2]
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
