      }
      const upperHex = '%' + hex1.toUpperCase() + hex2.toUpperCase()
      const charCode = parseInt(hex1 + hex2, 16)
      const char = String.fromCharCode(charCode)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += upperHex
      }
      i += 3
    } else {
      result += component[i]
      i++
    }
  }
  return result
