// Remove dot segments from path per RFC 3986 section 5.2.4
function removeDotSegments(path) {
  const input = path
  const output = []
  let i = 0

  while (i < input.length) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (input.startsWith('../', i)) {
      i += 3
    } else if (input.startsWith('./', i)) {
      i += 2
    }
    // B: If the input buffer begins with a prefix of "/./"
    else if (input.startsWith('/./')) {
      i += 2
    } else if (input === '/.') {
      i = input.length - 1
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (input.startsWith('/../', i)) {
      i += 3
      if (output.length > 0) {
        output.pop()
      }
    } else if (input === '/..') {
      i = input.length - 2
      if (output.length > 0) {
        output.pop()
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if (input === '.' || input === '..') {
      i = input.length
    }
    // E: Move the first path segment to output buffer
    else {
      let segmentEnd = i
      if (input[i] === '/') {
        segmentEnd++
      }
      while (segmentEnd < input.length && input[segmentEnd] !== '/') {
        segmentEnd++
      }
      output.push(input.slice(i, segmentEnd))
      i = segmentEnd
    }
  }

  return output.join('')
