/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parseUri, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}
const mode = argv[0]

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

const records = input.split('\n')
if (records.length > 0 && records[records.length - 1] === '') records.pop()

