  let output = ''
  let i = 0

  while (i < input.length) {
    const remaining = input.substring(i)

    // A: If the input buffer begins with a prefix of "../" or "./"
    if (remaining.startsWith('../')) {
      i += 3
    } else if (remaining.startsWith('./')) {
      i += 2
    }
    // B: If the input buffer begins with a prefix of "/./" or "/."
    else if (remaining.startsWith('/./')) {
      i += 2  // Skip "/.", leave the final "/"
    } else if (remaining === '/.') {
      output += '/'
      i = input.length
    }
    // C: If the input buffer begins with a prefix of "/../" or "/.."
    else if (remaining.startsWith('/../')) {
      i += 3  // Skip "/..", leave the final "/"
      const lastSlashIdx = output.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        output = output.substring(0, lastSlashIdx)
      }
    } else if (remaining === '/..') {
      output += '/'
      const lastSlashIdx = output.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        output = output.substring(0, lastSlashIdx)
      }
      i = input.length
    }
    // D: If the input buffer consists only of "." or ".."
    else if (remaining === '.' || remaining === '..') {
      i = input.length
    }
    // E: Move the first path segment to output buffer
    else {
      let segmentEnd = i
      if (input[i] === '/') {
        segmentEnd++
      }
      while (segmentEnd < input.length && input[segmentEnd] !== '/') {
        segmentEnd++
      }
      output += input.substring(i, segmentEnd)
      i = segmentEnd
    }
  }

  return output
}

// Normalize a URI
function normalizeURI(uri, lineNum) {
  const parsed = parseURI(uri)

  // Normalize scheme: lowercase
  if (parsed.scheme !== undefined) {
    parsed.scheme = parsed.scheme.toLowerCase()
  }

  // Normalize percent-encodings: userinfo, host, path, query, fragment (in that order)
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)

    if (auth.userinfo !== undefined) {
      auth.userinfo = normalizePercentEncodings(auth.userinfo, 'userinfo', lineNum)
    }

    if (auth.host !== undefined) {
      auth.host = normalizePercentEncodings(auth.host, 'host', lineNum)
    }

    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Normalize percent-encodings in path
  parsed.path = normalizePercentEncodings(parsed.path, 'path', lineNum)

  if (parsed.query !== undefined) {
    parsed.query = normalizePercentEncodings(parsed.query, 'query', lineNum)
  }

  if (parsed.fragment !== undefined) {
    parsed.fragment = normalizePercentEncodings(parsed.fragment, 'fragment', lineNum)
  }

  // Lowercase host
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)
    auth.host = auth.host.toLowerCase()
    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Drop default ports
  if (parsed.authority !== undefined) {
    const auth = parseAuthority(parsed.authority)
    if (auth.port !== undefined) {
      const defaultPorts = {
        'http': '80',
        'ws': '80',
        'https': '443',
        'wss': '443',
        'ftp': '21',
      }
      if (parsed.scheme && defaultPorts[parsed.scheme] === auth.port) {
        auth.port = undefined
      }
    }
    parsed.authority = reconstructAuthority(auth.userinfo, auth.host, auth.port)
  }

  // Remove dot segments from path
  parsed.path = removeDotSegments(parsed.path)

  // Add / to path when authority present and path empty
  if (parsed.authority !== undefined && parsed.path === '') {
    parsed.path = '/'
  }

  return reconstructURI(parsed.scheme, parsed.authority, parsed.path, parsed.query, parsed.fragment)
}

// Merge paths per RFC 3986 section 5.2.3
function mergePaths(basePath, baseAuthority, refPath) {
  if (baseAuthority !== undefined && basePath === '') {
    return '/' + refPath
  } else {
    const lastSlashIdx = basePath.lastIndexOf('/')
    if (lastSlashIdx !== -1) {
      return basePath.slice(0, lastSlashIdx + 1) + refPath
    } else {
      return refPath
    }
  }
}

// Resolve a reference against a base
function resolve(base, reference, lineNum) {
  const baseURI = parseURI(base)
  const refURI = parseURI(reference)

  let targetScheme = baseURI.scheme
  let targetAuthority = baseURI.authority
  let targetPath = baseURI.path
  let targetQuery = baseURI.query

  if (refURI.scheme !== undefined) {
    // Reference has a scheme: use it as-is
    targetScheme = refURI.scheme
    targetAuthority = refURI.authority
    targetPath = removeDotSegments(refURI.path)
    targetQuery = refURI.query
  } else {
    if (refURI.authority !== undefined) {
      // Reference has authority: use it
      targetAuthority = refURI.authority
      targetPath = removeDotSegments(refURI.path)
      targetQuery = refURI.query
    } else {
      if (refURI.path === '') {
        // Reference has empty path
        if (refURI.query !== undefined) {
          targetQuery = refURI.query
        }
      } else {
        if (refURI.path.startsWith('/')) {
          // Reference has absolute path
          targetPath = removeDotSegments(refURI.path)
        } else {
          // Reference has relative path: merge it
          targetPath = mergePaths(baseURI.path, baseURI.authority, refURI.path)
          targetPath = removeDotSegments(targetPath)
        }
        targetQuery = refURI.query
      }
    }
  }

  const targetFragment = refURI.fragment
  const target = reconstructURI(targetScheme, targetAuthority, targetPath, targetQuery, targetFragment)

  // Normalize the result
  return normalizeURI(target, lineNum)
}

// Main logic
const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
const stdin = readFileSync(0, 'utf8')
const lines = stdin.split('\n')

// Drop the empty tail a trailing newline leaves
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

for (let i = 0; i < lines.length; i++) {
  const lineNum = i + 1
  const line = lines[i]

  if (mode === 'normalize') {
    const result = normalizeURI(line, lineNum)
    console.log(result)
  } else {
    // resolve mode
    const spaceIdx = line.indexOf(' ')
    if (spaceIdx === -1) {
      process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
      process.exit(2)
    }

    const base = line.slice(0, spaceIdx)
    const reference = line.slice(spaceIdx + 1)

    // Check that base has a scheme
    const baseParsed = parseURI(base)
    if (baseParsed.scheme === undefined) {
      process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
      process.exit(2)
    }

    const result = resolve(base, reference, lineNum)
    console.log(result)
  }
}

process.exit(0)

